/* Official study sources and student-controlled AI question preparation. */
(()=>{'use strict';
const subjectNames=['국어','수학','영어','통합사회','통합과학','한국사','과학탐구실험·정보'];let feed=null,feedStatus='loading';
function safeLink(url){try{const u=new URL(url);return u.protocol==='https:'&&['openai.com','blog.google','deepmind.google','www.anthropic.com'].includes(u.hostname)?u.href:null}catch{return null}}
function officialView(){const s=feed?.school,matched=s?.name==='서초고등학교'&&s?.grade===1;const events=matched&&Array.isArray(s.events)?s.events.filter(x=>x&&valid(x.date)&&typeof x.title==='string'&&gap(x.date)>=0&&gap(x.date)<=30).slice(0,6):[];const articles=(Array.isArray(feed?.articles)?feed.articles:[]).filter(a=>a&&typeof a.title==='string'&&safeLink(a.url)&&Number.isFinite(Date.parse(a.published_at))&&Date.parse(a.published_at)<=Date.now()+600000&&Date.now()-Date.parse(a.published_at)<45*86400000&&(/교육|학습/.test(a.category||'')||/education|learning|classroom|student|study|teacher/i.test(a.title))).slice(0,3);return `<h3>🏫 서초고 1학년</h3>${feedStatus==='loading'?'<p class="muted">공식 자료를 확인하는 중이야…</p>':''}${matched&&s.status==='ok'?`<p class="muted">나이스 공개 학사일정 · 앞으로 30일</p>${events.length?events.map(x=>`<p class="school-event"><b>${esc(x.date)}</b> ${esc(x.title)}</p>`).join(''):'<p>현재 가져온 자료에 가까운 일정이 없어. 학교 공지도 확인해줘.</p>'}`:'<p>학교 일정은 공식 홈페이지에서 확인해줘. 자동으로 확인된 일정이 생기면 여기에 표시할게.</p>'}${matched&&s.status==='error'&&events.length?`<p class="muted">최근 갱신에 실패했어. 아래는 이전에 확인한 일정이니 학교 공지를 다시 확인해줘.</p>${events.map(x=>`<p>${esc(x.date)} · ${esc(x.title)}</p>`).join('')}`:''}<a href="https://seocho.sen.hs.kr/" target="_blank" rel="noopener">서초고 공지·학사일정 확인 ↗</a><p class="muted">반별 시험 범위·수행평가 기준은 학교에서 받은 안내문이 우선이야.</p><h3>📖 지금 필요한 학습 자료</h3><div class="source-links"><a href="hub.html">학습 사이트 9곳 모음 →</a><a href="https://www.ebsi.co.kr/" target="_blank" rel="noopener">EBSi 고1 강의·기출 ↗</a><a href="./#shiro-news">AI·학습 소식 더 보기 →</a></div>${articles.length?`<h3>이번에 확인한 학습 소식</h3>${articles.map(a=>`<p><a href="${esc(safeLink(a.url))}" target="_blank" rel="noopener">${esc(a.title)}</a><br><small class="muted">${esc(a.source)} · ${esc(a.published_at.slice(0,10))}</small></p>`).join('')}`:''}${feed?.checked_at&&Number.isFinite(Date.parse(feed.checked_at))?`<p class="muted">자료 확인: ${esc(new Date(feed.checked_at).toLocaleString('ko-KR'))}${Date.now()-Date.parse(feed.checked_at)>86400000?' · 하루 이상 지난 자료야. 최신 내용은 원문을 확인해줘.':''}</p>`:feedStatus==='error'?'<p class="muted">자료를 불러오지 못했어. 위 공식 사이트에서 확인해줘.</p>':''}`}
function helpView(){return `<details class="card" id="study-question-builder"><summary>🧠 막힌 문제, 질문부터 정리하기</summary><p>문제와 내 풀이를 적으면 AI나 선생님께 물어볼 질문으로 정리해줘.</p><form id="study-question-form"><label>질문할 과목<select name="subject">${subjectNames.map(s=>`<option>${s}</option>`).join('')}</select></label><label>문제·궁금한 내용<textarea name="problem" required maxlength="3000" placeholder="문제를 적고, 그림이 있다면 주어진 조건도 설명해줘."></textarea></label><label>내가 해본 풀이<textarea name="attempt" maxlength="1500" placeholder="여기까지 풀어봤어…"></textarea></label><label>막힌 부분<select name="stuck"><option>문제의 뜻</option><option>개념과 조건</option><option>풀이 첫 단계</option><option>계산·문장 표현</option><option>내 풀이가 맞는지</option></select></label><button class="primary">질문 정리하기</button></form><section id="study-question-result" hidden><label>정리된 질문<textarea id="study-question-output" readonly rows="10"></textarea></label><div class="actions"><button id="study-copy-question">📋 질문 복사</button><a class="button-link" href="https://chatgpt.com/" target="_blank" rel="noopener">ChatGPT 열기 ↗</a></div><p class="muted">복사한 질문을 새 창에 직접 붙여넣어줘. 이 버튼은 내용을 자동 전송하지 않아. 답변의 조건과 계산은 교과서·공식 해설로 확인해줘.</p></section></details>`}
function makePrompt(subject,problem,attempt,stuck){return `고등학교 1학년 ${subject} 공부를 도와줘.\n\n[문제·질문]\n${problem}\n\n[내가 해본 풀이]\n${attempt||'아직 풀이를 시작하지 못했어.'}\n\n[막힌 부분]\n${stuck}\n\n다음 순서로 도와줘.\n1. 문제에 빠진 조건이나 그림 정보가 있으면 먼저 물어봐. 추측하지 마.\n2. 필요한 개념을 쉬운 말로 설명해줘.\n3. 정답 전체를 바로 보여주지 말고 첫 단계 힌트 하나를 줘.\n4. 내가 시도한 뒤 다음 힌트와 풀이를 이어가줘.\n5. 풀이의 조건·계산·단위를 확인하고, 마지막에 비슷한 확인 문제 1개를 줘.\n6. 불확실한 내용은 불확실하다고 말해줘.`}
const priorRender=render;render=function(){priorRender();if(tab==='today'||tab==='table')root.insertAdjacentHTML('beforeend',`<details class="card"><summary>🏫 학교·학습 자료 확인</summary><div id="study-official-sources">${officialView()}</div></details>`);if(tab==='review')root.insertAdjacentHTML('beforeend',helpView())};
document.addEventListener('submit',e=>{if(e.target.id!=='study-question-form')return;e.preventDefault();const d=new FormData(e.target),problem=String(d.get('problem')||'').trim();if(!problem)return;document.querySelector('#study-question-output').value=makePrompt(String(d.get('subject')),problem,String(d.get('attempt')||'').trim(),String(d.get('stuck')));document.querySelector('#study-question-result').hidden=false;document.querySelector('#study-question-output').focus()});
document.addEventListener('click',async e=>{if(e.target.closest('#study-copy-question')){const box=document.querySelector('#study-question-output');try{await navigator.clipboard.writeText(box.value);notice('질문을 복사했어. AI나 선생님께 직접 전달해줘.')}catch{box.focus();box.select();notice('질문을 선택했어. 복사 메뉴를 눌러줘.')}}});
async function loadFeed(){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{const response=await fetch('news.json',{cache:'no-cache',signal:controller.signal});if(!response.ok)throw Error('fetch');const data=await response.json();if(!data||typeof data!=='object')throw Error('shape');feed=data;feedStatus='ok'}catch{feedStatus='error'}finally{clearTimeout(timeout);const box=document.querySelector('#study-official-sources');if(box)box.innerHTML=officialView()}}
render();loadFeed();
})();
